mapper.select:
SELECT 

		ISNULL(MIN(OS.납기일자), #{searchDtFrom}) AS OS_MAX_DATE


		ISNULL(MIN(OS.수주일자), #{searchDtFrom}) AS OS_MAX_DATE





		 AND OS.납기일자 >= #{listStartDt} 


		 AND OS.수주일자 >= #{listStartDt}

SELECT 

		ISNULL(MIN(WO.납기일자), #{searchDtFrom}) AS W_MAX_DATE


		ISNULL(MIN(WO.접수일자), #{searchDtFrom}) AS W_MAX_DATE





		 AND WO.납기일자 >= #{listStartDt} 


		 AND WO.접수일자 >= #{listStartDt}

mapper.sql:
WHERE 1=1
AND ( UPPER(RTRIM(BPLC.사업장명칭)) LIKE UPPER('%'+ #{searchBplcNm} +'%') OR UPPER(RTRIM(BPLC.사업장)) LIKE UPPER('%'+ #{searchBplcNm} +'%') )
AND OS.수주사업장 = #{searchBplcCode}
AND ( (SELECT UPPER(RTRIM(CM2.상호)) FROM 거래처MASTER CM2 WHERE CM2.등록사업장 = OS.수주사업장 AND CM2.거래처코드 = OS.거래처코드) LIKE UPPER('%'+ RTRIM(#{searchBcncNm}) +'%') OR (SELECT UPPER(RTRIM(CM2.거래처코드)) FROM 거래처MASTER CM2 WHERE CM2.등록사업장 = OS.수주사업장 AND CM2.거래처코드 = OS.거래처코드) LIKE UPPER('%'+ RTRIM(#{searchBcncNm}) +'%') )
AND OS.거래처코드 = #{searchBcncCode}
AND ( ( SELECT UPPER(RTRIM(CM2.상호)) FROM 거래처MASTER CM2 WHERE CM2.등록사업장 = OS.수주사업장 AND CM2.거래처코드 = ( CASE WHEN LEN(OS.착지업체) < 1 THEN RTRIM(OS.거래처코드) ELSE RTRIM(OS.착지업체) END)) LIKE UPPER('%'+ RTRIM(#{searchEntrpsNm}) +'%') OR ( SELECT UPPER(RTRIM(CM2.거래처코드)) FROM 거래처MASTER CM2 WHERE CM2.등록사업장 = OS.수주사업장 AND CM2.거래처코드 = ( CASE WHEN LEN(OS.착지업체) < 1 THEN RTRIM(OS.거래처코드) ELSE RTRIM(OS.착지업체) END)) LIKE UPPER('%'+ RTRIM(#{searchEntrpsNm}) +'%') )
AND OS.착지업체 = #{searchDlvyEntrps}
AND ( UPPER(RTRIM(IC.품목명)) LIKE UPPER('%'+ RTRIM(#{searchItemNm}) +'%') OR UPPER(RTRIM(IC.품목코드)) LIKE UPPER('%'+ RTRIM(#{searchItemNm}) +'%')
)
AND OS.납기일자 >= #{searchDtFrom}
AND OS.납기일자 <= #{searchDtTo}
AND OS.수주일자 >= #{searchDtFrom}
AND OS.수주일자 <= #{searchDtTo}

WHERE 1=1 AND WO.접수확인 = 'N' AND WO.접수삭제 = 'N' AND WO.진행유무 = 'Y'
AND ( UPPER(BPLC.사업장명칭) LIKE UPPER('%'+ RTRIM(#{searchBplcNm}) +'%') OR UPPER(BPLC.사업장) LIKE UPPER('%'+ RTRIM(#{searchBplcNm}) +'%') )
AND WO.단가사업장 = #{searchBplcCode}
AND ( ( SELECT UPPER(RTRIM(CM2.상호)) FROM 거래처MASTER CM2 WHERE CM2.등록사업장 = WO.단가사업장 AND CM2.거래처코드 = WO.거래처코드) LIKE UPPER('%'+ RTRIM(#{searchBcncNm}) +'%') OR ( SELECT UPPER(RTRIM(CM2.거래처코드)) FROM 거래처MASTER CM2 WHERE CM2.등록사업장 = WO.단가사업장 AND CM2.거래처코드 = WO.거래처코드) LIKE UPPER('%'+ RTRIM(#{searchBcncNm}) +'%') )
AND WO.거래처코드 = #{searchBcncCode}
AND ( (SELECT UPPER(RTRIM(CM2.상호)) FROM 거래처MASTER CM2 WHERE CM2.거래처코드 = WO.착지업체 AND CM2.등록사업장 = WO.단가사업장) LIKE UPPER('%'+ RTRIM(#{searchEntrpsNm}) +'%') OR (SELECT UPPER(RTRIM(CM2.거래처코드)) FROM 거래처MASTER CM2 WHERE CM2.거래처코드 = WO.착지업체 AND CM2.등록사업장 = WO.단가사업장) LIKE UPPER('%'+ RTRIM(#{searchEntrpsNm}) +'%')
)
AND WO.착지업체 = #{searchDlvyEntrps}
AND ( UPPER(RTRIM(IC.품목명)) LIKE UPPER('%'+ RTRIM(#{searchItemNm}) +'%') OR UPPER(RTRIM(IC.품목코드)) LIKE UPPER('%'+ RTRIM(#{searchItemNm}) +'%')
)
AND WO.납기일자 >= #{searchDtFrom}
AND WO.납기일자 <= #{searchDtTo}
AND WO.접수일자 >= #{searchDtFrom}
AND WO.접수일자 <= #{searchDtTo}

update.foreach:
UPDATE 웹주문접수 SET
	접수삭제 = 'Y'
	, 수정자 = #{bcncCode}
	, 수정일자 = CONVERT(VARCHAR,GETDATE(),112)
	, 수정시간 = REPLACE(CONVERT(VARCHAR,GETDATE(),108),':','')
WHERE 접수일자 = #{item.wRceptde}
	AND 일련번호 = #{item.wSn}

mapper.update:
UPDATE 일마감관리 SET
	수주최종번호 = #{chgNum}
WHERE 사업장 = #{bplcCode}
AND 마감일자 = CONVERT(VARCHAR,GETDATE(),112)

update.foreach:
UPDATE 웹주문접수 SET
	주문사업장 = WO.출고사업장
	, 주문일자 = CONVERT(VARCHAR,GETDATE(),112)
	, 주문번호 = #{item.osInsNo}
	, 관리자재고중량 = #{item.wInvntryQy}
	, 접수확인 = 'Y'
	, 확인자 = #{bcncCode}
	, 확인일자 = CONVERT(VARCHAR,GETDATE(),112)
	, 확인시간 = REPLACE(CONVERT(VARCHAR,GETDATE(),108),':','')
FROM 웹주문접수 WO 
WHERE 접수일자 = #{item.wRceptde}
	AND 일련번호 = #{item.wSn}
